import html,json,os,pathlib,re,shutil,subprocess,sys
out=pathlib.Path(sys.argv[1] if len(sys.argv)>1 else '_publish')
if out.exists(): raise SystemExit('Refusing to overwrite output directory')
out.mkdir(parents=True)
for name in subprocess.check_output(['git','ls-files','-z']).decode().split('\0'):
 if not name: continue
 p=pathlib.Path(name)
 if any(x.startswith('.') for x in p.parts) or p.parts[0] in {'src','scripts','docs','_archive','node_modules','preview'}: continue
 if p.name!='CNAME' and p.suffix.lower() not in {'.html','.css','.js','.svg','.png','.jpg','.jpeg','.webp','.gif','.ico','.woff','.woff2','.ttf','.csv','.json','.txt','.xml','.pdf','.mp4','.webm'}: continue
 if p.is_file() and not p.is_symlink():
  f=out/p;f.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(p,f)
if (out/'CNAME').read_text().strip()!='beiz.com.au': raise SystemExit('Domain mismatch')
css="""*{box-sizing:border-box}body{margin:0;background:#f8f7f2;color:#1b2926;font:16px/1.65 system-ui,sans-serif}a{color:inherit;text-underline-offset:4px}a:focus-visible,summary:focus-visible{outline:3px solid #ad7b25;outline-offset:4px}.ed-wrap{width:min(1140px,calc(100% - 40px));margin:auto}.ed-head,.ed-foot{background:white;border-block:1px solid #bccbbf}.ed-bar{min-height:104px;display:flex;align-items:center;justify-content:space-between;gap:22px}.ed-id{display:flex;align-items:center;gap:24px}.ed-brand{font:800 29px/1 system-ui;letter-spacing:4px;text-decoration:none}.ed-brand small{display:block;font:10px/1.5 system-ui;letter-spacing:1px;margin-top:7px}.ed-ca{width:62px;height:auto;border-left:1px solid #bccbbf;padding-left:15px;box-sizing:content-box}.ed-nav{display:flex;gap:28px;font:14px/1.5 system-ui}.ed-nav a{text-decoration:none}.ed-tm,.ed-legal{font:11px/1.6 system-ui;color:#52675a}.ed-tm{padding-bottom:8px}.ed-mobile{display:none}.ed-intro{padding:60px 0 40px;border-bottom:1px solid #bccbbf}.ed-intro h1{font:550 clamp(38px,5vw,60px)/1.1 system-ui;letter-spacing:-2px;max-width:850px;margin:15px 0 25px}.ed-deck{font:20px/1.6 system-ui;color:#4a6052;max-width:760px}.ed-kicker,.ed-num{font:11px/1.6 ui-monospace,monospace;text-transform:uppercase;letter-spacing:1px;color:#476653}.ed-section{padding:44px 0}.ed-row{display:grid;grid-template-columns:45px 1fr 170px;gap:22px;border-top:1px solid #9daf9f;padding:27px 0}.ed-row:last-child{border-bottom:1px solid #9daf9f}.ed-row h2{font:600 23px/1.3 system-ui;margin:0 0 10px}.ed-row p{color:#52675a;margin:0;max-width:650px}.ed-row a{align-self:center;font-size:14px}.ed-proof{padding:28px;background:#173e32;color:white}.ed-proof p{color:#d2e2d6;font-size:13px}.ed-table{width:100%;border-collapse:collapse}.ed-table td{padding:13px 5px;border-bottom:1px solid #5c7a68}.ed-prose{max-width:800px}.ed-prose h2{font:600 26px/1.3 system-ui}.ed-links{display:flex;flex-wrap:wrap;gap:24px;margin:22px 0;font:13px/1.6 system-ui}.ed-foot{padding:30px 0}.ed-legal p{margin:8px 0}@media(max-width:850px){.ed-nav{display:none}.ed-mobile{display:block;position:relative}.ed-mobile div{position:absolute;right:0;background:white;padding:15px;min-width:190px;border:1px solid #bccbbf;z-index:9}.ed-mobile a{display:block;padding:8px}.ed-row{grid-template-columns:30px 1fr}.ed-row>a{grid-column:2}.ed-intro{padding:35px 0}.ed-intro h1{font-size:43px}.ed-deck{font-size:18px}.ed-ca{width:48px;padding-left:12px}.ed-id{gap:12px}.ed-brand{font-size:25px}.ed-wrap{width:calc(100% - 32px)}}"""
(out/'assets').mkdir(exist_ok=True);(out/'assets/editorial.css').write_text(css)
brand='<a class="ed-brand" href="/">BEIZ<small>DATA &amp; ACCOUNTING</small></a>'
links='<a href="/services/">Work</a><a href="/tools/">Tools</a><a href="/notes/">Notes</a><a href="/contact/">Contact</a>'
header='<header class="ed-head"><div class="ed-wrap ed-bar"><div class="ed-id">'+brand+'<img class="ed-ca" src="/assets/media/ca-logo-vertical.svg" alt="Chartered Accountants Australia and New Zealand" width="96" height="108"></div><nav class="ed-nav" aria-label="Main">'+links+'</nav><details class="ed-mobile"><summary>Menu</summary><div>'+links+'</div></details></div><div class="ed-wrap ed-tm">Trade mark of Chartered Accountants Australia and New Zealand and used with permission.</div></header>'
footer='<footer class="ed-foot"><div class="ed-wrap">'+brand+'<div class="ed-links">'+links+'<a href="/about/">About</a><a href="/prices/">Fees</a><a href="/privacy/">Privacy</a></div><div class="ed-legal"><p>Beiz Data &amp; Accounting Pty Ltd · ABN 53 691 755 496 · ACN 691 755 496 · Canberra, ACT</p><p>No tax returns, BAS or GST lodgements, tax or BAS agent services, statutory audit or assurance, legal advice or financial product advice.</p><p>Liability limited by a scheme approved under Professional Standards Legislation. Professional indemnity insurance held with Chubb.</p><p>Trade mark of Chartered Accountants Australia and New Zealand and used with permission.</p><p>© 2026 Beiz Data &amp; Accounting Pty Ltd</p></div></div></footer>'
def page(path,title,body,styles='',scripts='',robots=''):
 canonical='https://beiz.com.au/'+('' if path=='index.html' else path.removesuffix('index.html'))
 return '<!doctype html><html lang="en-AU" data-design="editorial-v1"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+html.escape(title)+'</title><link rel="canonical" href="'+canonical+'">'+robots+styles+'<link rel="stylesheet" href="/assets/editorial.css"></head><body>'+header+'<main id="main">'+body+'</main>'+footer+scripts+'</body></html>'
def intro(k,h,p): return '<section class="ed-intro"><div class="ed-wrap"><p class="ed-kicker">'+k+'</p><h1>'+h+'</h1><p class="ed-deck">'+p+'</p></div></section>'
def row(n,h,p,url,cta): return '<article class="ed-row"><span class="ed-num">'+n+'</span><div><h2>'+h+'</h2><p>'+p+'</p></div><a href="'+url+'">'+cta+' →</a></article>'
primary={
'index.html':('Beiz | Finance, data and systems',intro('Australian finance-and-technology practice','Finance, data<br>and systems.','We build reporting and reconciliation tools for teams working across accounting software, spreadsheets and operational systems.')+'<section class="ed-section"><div class="ed-wrap">'+row('01','Reporting that can be repeated.','Document the records, checks and refresh process behind a report or dashboard.','/services/','Explore the work')+row('02','Differences you can investigate.','Compare approved time with invoices and credits; inspect the supporting records.','/demo/project-billing/','Run the demo')+row('03','Tools worth opening.','Working examples with visible limits. No fictional performance dashboard or checkout.','/tools/','Open the tools')+'</div></section><section class="ed-section"><div class="ed-wrap"><div class="ed-proof"><h2>A billing difference is a question, not a saving.</h2><table class="ed-table"><tbody><tr><td>Approved time × supplied rate</td><td>A$1,500</td></tr><tr><td>Invoice records less credit</td><td>A$1,000</td></tr><tr><td>Difference to investigate</td><td>A$500</td></tr></tbody></table><p>Invented project. Check terms, periods and billability. Not client results or recovered revenue.</p><a href="/demo/project-billing/">Inspect the records →</a></div><div class="ed-links"><a href="/contact/">Discuss a project →</a><a href="/about/">About Beiz →</a></div></div></section>'),
'services/index.html':('Work with Beiz',intro('Work / Implementation','One recurring problem.<br>A clear handover.','Scoped reporting, reconciliation and data-system projects alongside your existing team.')+'<section class="ed-section"><div class="ed-wrap ed-prose"><h2>Reporting and data preparation</h2><p>Agree the source records and reconciliation baseline. Build a repeatable management report or dashboard with documented refresh steps.</p><h2>Reconciliation workflows</h2><p>Compare agreed records and periods. Make differences traceable without assuming every exception is recoverable money.</p><h2>Practical automation</h2><p>Define the process, decision owner, access and acceptance checks. Use AI only where suitable and evaluated.</p><h2>Written scope and fee</h2><p>Agree deliverables, exclusions, payment terms, handover and any ongoing support. This is not a promise to replace every responsibility of a permanent hire.</p><div class="ed-links"><a href="/contact/">Describe the work →</a><a href="/prices/">Existing fee information →</a></div></div></section>'),
 'tools/index.html':('Beiz | Tools',intro('Tools / Beiz lab','Inspect the work.','Tools and labelled demonstrations, not unearned performance claims.')+'<section class="ed-section"><div class="ed-wrap">'+row('01','Project billing reconciliation','Invented sample: compare time, invoices and credits; record a review decision and export exceptions.','/demo/project-billing/','Open demo')+row('02','Payables exception check','Selected checks on an invoice export. A flag is not a fraud finding or payment approval.','/bill-check/','Open check')+'<p class="ed-legal">Paid digital products are not enabled. Finished files, terms, payment and fulfilment need testing before sale.</p></div></section>'),
 'notes/index.html':('Beiz | Notes',intro('Notes / Methods','Fewer claims.<br>More explanation.','Practical notes on making a financial workflow inspectable.')+'<section class="ed-section"><div class="ed-wrap ed-prose"><h2>A billing gap is not recovered revenue.</h2><p>Milestones, deposits, credits, timing or incorrect inputs may explain a difference. Keep calculations separate from the billability decision.</p><h2>A forecast depends on assumptions.</h2><p>Correct arithmetic does not establish that expected receipts, amounts or payment dates are realistic. Test alternative scenarios.</p><h2>A demo is not a production control.</h2><p>Production work also needs agreed access, identity, logs, failure handling and named review responsibilities.</p><a href="/demo/project-billing/">Inspect the billing example →</a></div></section>'),
 'about/index.html':('About Beiz',intro('About / The practice','Finance expertise.<br>Applied to the systems.','A Canberra-based practice combining finance, data and governance skills with practical implementation.')+'<section class="ed-section"><div class="ed-wrap ed-prose"><h2>Principal-led</h2><p>You work with Purav Mehta CA, GAICD. Each engagement has a defined scope, deliverables and review responsibilities.</p><h2>Practice and lab</h2><p>The practice delivers scoped work. The lab demonstrates reusable methods and tools. Prototypes are not presented as certified controls or regulated platforms.</p><h2>Clear boundaries</h2><p>Your existing accountant and specialist advisers retain their responsibilities. Beiz does not provide the services excluded in the footer.</p><a href="/contact/">Discuss a project →</a></div></section>')}
wrapped=0
for f in list(out.rglob('*.html')):
 path=f.relative_to(out).as_posix()
 if path in primary: continue
 text=f.read_text(encoding='utf-8',errors='replace');m=re.search(r'<main\b[^>]*>([\s\S]*?)</main>',text,re.I)
 if not m: continue
 body=re.sub(r'<img\b[^>]*purav-mehta[^>]*>','',m.group(1),flags=re.I)
 title=re.search(r'<title>([\s\S]*?)</title>',text,re.I)
 title=html.unescape(title.group(1)) if title else 'Beiz'
 h=re.search(r'<head\b[^>]*>([\s\S]*?)</head>',text,re.I)
 styles=''.join(re.findall(r'<style\b[^>]*>[\s\S]*?</style>|<link\b[^>]*rel=["\']stylesheet["\'][^>]*>',h.group(1),re.I)) if h else ''
 scripts=''.join(s for s in re.findall(r'<script\b[^>]*>[\s\S]*?</script>',text,re.I) if 'webmcp.js' not in s.lower() and 'application/ld+json' not in s.lower())
 body=re.sub(r'<script\b[^>]*>[\s\S]*?</script>','',body,flags=re.I)
 robots=''.join(re.findall(r'<meta\b[^>]*name=["\']robots["\'][^>]*>',text,re.I))
 f.write_text(page(path,title,body,styles,scripts,robots),encoding='utf-8');wrapped+=1
for path,(title,body) in primary.items():
 f=out/path;f.parent.mkdir(parents=True,exist_ok=True);f.write_text(page(path,title,body),encoding='utf-8')
(out/'.nojekyll').touch();release={'commit':os.environ.get('GITHUB_SHA','local-test'),'design':'editorial-v1','primary_pages':len(primary),'legacy_pages_rewrapped':wrapped}
(out/'release.json').write_text(json.dumps(release));home=(out/'index.html').read_text()
assert 'data-design="editorial-v1"' in home and 'ca-logo-vertical.svg' in home and 'purav-mehta' not in home
print(json.dumps(release))
